#!/usr/bin/env python3
"""Payroll summary for one pay period.

Usage: python3 payroll.py INPUT_DIR OUTPUT_FILE

Reads the clock exports, employee list, rates, corrections and pay period
from INPUT_DIR (as described in docs/exports.md) and writes the payroll
summary (as described in docs/output.md) to OUTPUT_FILE, following the
rules in docs/payroll-rules.md. Standard library only.
"""

import calendar
import csv
import gzip
import json
import os
import sys
from collections import defaultdict
from datetime import date, datetime, timedelta, timezone
from decimal import Decimal, ROUND_HALF_UP
from zoneinfo import ZoneInfo

UTC = timezone.utc
US = 1_000_000  # microseconds per second
MIN_US = 60 * US
HOUR_US = 3600 * US
DAY_US = 86400 * US
ROUND_US = 360 * US  # 6 minutes
HALF_ROUND_US = 180 * US
DUP_US = 300 * US
MAX_SHIFT_US = 16 * HOUR_US
EPOCH = datetime(1970, 1, 1, tzinfo=UTC)


def to_us(dt):
    """Microseconds since the epoch for an aware datetime, exactly."""
    u = dt.astimezone(UTC)
    return calendar.timegm(u.timetuple()) * US + u.microsecond


def dt_from_us(epoch_us, tz):
    """Aware datetime in tz for an epoch-microsecond instant."""
    return (EPOCH + timedelta(microseconds=epoch_us)).astimezone(tz)


def parse_iso_us(text):
    """Parse an ISO 8601 timestamp with UTC offset into epoch microseconds."""
    t = text.strip()
    if t.endswith("Z") or t.endswith("z"):
        t = t[:-1] + "+00:00"
    return to_us(datetime.fromisoformat(t))


def wall_to_us(naive, zone, fold):
    """Turn a naive local wall time into epoch microseconds (fold picks
    the first occurrence, 0, or the second, 1, of a repeated local time)."""
    return to_us(naive.replace(tzinfo=zone, fold=fold))


def read_export_text(path):
    with open(path, "rb") as fh:
        raw = fh.read()
    if raw[:2] == b"\x1f\x8b":
        raw = gzip.decompress(raw)
    return raw.decode("utf-8")


# ---------------------------------------------------------------------------
# Format parsers. Each yields (punch_id, employee, direction, epoch_us).
# ---------------------------------------------------------------------------

def parse_abbr_csv(text):
    """abbr-csv: header may repeat mid-file with columns in another order;
    Time may switch to a 24-hour clock without AM/PM."""
    col_index = None
    out = []
    for row in csv.reader(text.splitlines()):
        if not row or all(not c.strip() for c in row):
            continue
        names = [c.strip() for c in row]
        if "Badge" in names and "Record" in names:
            col_index = {name: i for i, name in enumerate(names)}
            continue
        if col_index is None:
            continue
        try:
            badge = row[col_index["Badge"]].strip()
            punch = row[col_index["Punch"]].strip().upper()
            date_s = row[col_index["Date"]].strip()
            time_s = row[col_index["Time"]].strip()
            zone_s = row[col_index["Zone"]].strip()
            record = row[col_index["Record"]].strip()
            terminal = row[col_index["Terminal"]].strip()
        except IndexError:
            continue
        if not record:
            continue
        month, day, year = (int(p) for p in date_s.split("/"))
        upper = time_s.upper()
        if upper.endswith("AM") or upper.endswith("PM"):
            dt = datetime.strptime(time_s, "%I:%M:%S %p")
            hour, minute, second = dt.hour, dt.minute, dt.second
        else:
            hms = time_s.split(":")
            hour, minute, second = int(hms[0]), int(hms[1]), int(hms[2])
        naive = datetime(year, month, day, hour, minute, second)
        is_dst = zone_s.endswith("DT")
        out.append((record, badge, punch, (naive, is_dst, terminal)))
    return out


def abbr_resolve(rows, zone):
    for record, badge, punch, (naive, is_dst, _terminal) in rows:
        yield record, badge, punch, wall_to_us(naive, zone, 0 if is_dst else 1)


def parse_epoch_jsonl(text):
    schema = 1
    out = []
    for line in text.splitlines():
        line = line.strip()
        if not line:
            continue
        obj = json.loads(line)
        if obj.get("heartbeat") is True:
            continue
        if obj.get("schema") == 2:
            schema = 2
            continue
        if schema == 1:
            if "schema" in obj:
                continue
            pid = str(obj["id"])
            emp = str(obj["emp"])
            direction = str(obj["dir"]).upper()
            if "ts_ms" in obj:
                epoch_us = int(obj["ts_ms"]) * 1000
            else:
                epoch_us = int(obj["ts"]) * US
        else:
            pid = str(obj["punch_id"])
            emp = str(obj["employee"])
            direction = str(obj["direction"]).upper()
            epoch_us = int(obj["epoch_ms"]) * 1000
        out.append((pid, emp, direction, epoch_us))
    return out


def parse_offset_csv(text):
    out = []
    lines = text.splitlines()
    reader = csv.reader(lines, delimiter=";")
    header = None
    for row in reader:
        if not row or all(not c.strip() for c in row):
            continue
        if header is None:
            header = [c.strip() for c in row]
            continue
        rec = dict(zip(header, row))
        pid = rec["punch_id"].strip()
        emp = rec["employee"].strip()
        event = rec["event"].strip()
        direction = "IN" if event == "clock_in" else "OUT"
        epoch_us = parse_iso_us(rec["timestamp"])
        out.append((pid, emp, direction, epoch_us))
    return out


def standard_offset_us(zone, year):
    """The zone's standard (non-DST) UTC offset in microseconds."""
    for month in range(1, 13):
        probe = datetime(year, month, 15, 12, tzinfo=zone)
        if probe.dst() == timedelta(0):
            return int(probe.utcoffset().total_seconds()) * US
    probe = datetime(year, 1, 15, 12, tzinfo=zone)
    return int(probe.utcoffset().total_seconds()) * US


def parse_legacy_fixed(text, zone):
    std_us = standard_offset_us(zone, 2026)
    cur_us = std_us
    out = []
    for raw_line in text.splitlines():
        line = raw_line.rstrip("\r\n")
        if not line:
            continue
        kind = line[0]
        if kind == "H":
            off = ""
            if len(line) >= 18:
                off = line[13:18]
            if len(off) == 5 and off[0] in "+-" and off[1:].isdigit():
                sign = 1 if off[0] == "+" else -1
                cur_us = sign * ((int(off[1:3]) * 60 + int(off[3:5])) * MIN_US)
            else:
                cur_us = std_us
        elif kind == "D":
            pid = line[1:9]
            badge = line[9:15].strip()
            emp = "E" + badge
            direction = "IN" if line[15] == "I" else "OUT"
            stamp = line[16:30]
            naive = datetime.strptime(stamp, "%Y%m%d%H%M%S")
            naive_us = calendar.timegm(naive.timetuple()) * US
            epoch_us = naive_us - cur_us
            out.append((pid, emp, direction, epoch_us))
        # 'T' trailers and anything else carry no punch.
    return out


def parse_de_tsv(text):
    out = []
    lines = [l for l in text.splitlines() if l.strip()]
    header = [c.strip() for c in lines[0].split("\t")]
    idx = {name: i for i, name in enumerate(header)}
    for line in lines[1:]:
        parts = line.split("\t")
        emp = parts[idx["Ausweis"]].strip()
        direction = "IN" if parts[idx["Buchung"]].strip() == "K" else "OUT"
        day, month, year = (int(p) for p in parts[idx["Datum"]].strip().split("."))
        hm = parts[idx["Uhrzeit"]].strip().split(":")
        naive = datetime(year, month, day, int(hm[0]), int(hm[1]), 0)
        zone_s = parts[idx["Zeitzone"]].strip()
        is_dst = zone_s == "MESZ"
        pid = parts[idx["Nr"]].strip()
        out.append((pid, emp, direction, (naive, is_dst)))
    return out


def parse_local_csv(text):
    out = []
    lines = [l for l in text.splitlines() if l.strip()]
    reader = csv.reader(lines)
    header = None
    for row in reader:
        if not row or all(not c.strip() for c in row):
            continue
        if header is None:
            header = [c.strip() for c in row]
            continue
        rec = dict(zip(header, row))
        emp = rec["employee_id"].strip()
        direction = rec["direction"].strip().upper()
        naive = datetime.strptime(rec["local_time"].strip(), "%Y-%m-%d %H:%M:%S")
        pid = rec["punch_ref"].strip()
        out.append((pid, emp, direction, naive))
    return out


def parse_local_jsonl(text):
    out = []
    for line in text.splitlines():
        line = line.strip()
        if not line:
            continue
        obj = json.loads(line)
        punch = obj.get("punch")
        if not isinstance(punch, dict):
            continue
        pid = str(punch["id"])
        emp = str(punch["badge"])
        direction = str(punch["type"]).upper()
        naive = datetime.strptime(str(punch["at"]), "%Y-%m-%d %H:%M:%S")
        out.append((pid, emp, direction, naive))
    return out


PARSERS = {
    "abbr-csv": parse_abbr_csv,
    "epoch-jsonl": parse_epoch_jsonl,
    "offset-csv": parse_offset_csv,
    "legacy-fixed": parse_legacy_fixed,
    "de-tsv": parse_de_tsv,
    "local-csv": parse_local_csv,
    "local-jsonl": parse_local_jsonl,
}


# ---------------------------------------------------------------------------
# Main pipeline.
# ---------------------------------------------------------------------------

class Punch:
    __slots__ = ("site", "pid", "employee", "direction", "epoch_us",
                 "rounded_us", "offset_us")

    def __init__(self, site, pid, employee, direction, epoch_us):
        self.site = site
        self.pid = pid
        self.employee = employee
        self.direction = direction
        self.epoch_us = epoch_us
        self.rounded_us = None
        self.offset_us = None


def collect_punches(input_dir, sites):
    """Step 1: read every export of every site; dedupe by (site, punch id)."""
    punches = {}
    export_keys = set()
    export_dir = os.path.join(input_dir, "exports")
    for site, info in sites.items():
        zone = info["zone"]
        fmt = info["format"]
        parser = PARSERS[fmt]
        sdir = os.path.join(export_dir, site)
        try:
            names = sorted(os.listdir(sdir))
        except OSError:
            continue
        for name in names:
            path = os.path.join(sdir, name)
            if not os.path.isfile(path):
                continue
            text = read_export_text(path)
            if fmt == "legacy-fixed":
                rows = parser(text, zone)
            else:
                rows = parser(text)
            if fmt == "abbr-csv":
                rows = list(abbr_resolve(rows, zone))
            elif fmt == "de-tsv":
                rows = [(pid, emp, d, wall_to_us(n, zone, 0 if dst else 1))
                        for pid, emp, d, (n, dst) in rows]
            elif fmt in ("local-csv", "local-jsonl"):
                rows = [(pid, emp, d, wall_to_us(n, zone, 0))
                        for pid, emp, d, n in rows]
            for pid, emp, direction, epoch_us in rows:
                key = (site, pid)
                if key in punches:
                    continue
                punches[key] = Punch(site, pid, emp, direction, epoch_us)
                export_keys.add(key)
    return punches, export_keys


def apply_corrections(input_dir, punches, export_keys, cutoff_us):
    """Step 2: apply corrections in (issued_at, correction_id) order."""
    cdir = os.path.join(input_dir, "corrections")
    try:
        names = sorted(os.listdir(cdir))
    except OSError:
        names = []
    rows = []
    for name in names:
        path = os.path.join(cdir, name)
        if not os.path.isfile(path):
            continue
        with open(path, "r", encoding="utf-8", newline="") as fh:
            for rec in csv.DictReader(fh):
                if rec is None:
                    continue
                cid = (rec.get("correction_id") or "").strip()
                if not cid:
                    continue
                rows.append(rec)
    rows.sort(key=lambda r: (parse_iso_us(r["issued_at"]),
                             (r.get("correction_id") or "").strip()))
    applied = 0
    for rec in rows:
        issued_us = parse_iso_us(rec["issued_at"])
        if issued_us > cutoff_us:
            continue
        action = (rec.get("action") or "").strip()
        site = (rec.get("site") or "").strip()
        pid = (rec.get("punch_id") or "").strip()
        key = (site, pid)
        if action == "void":
            if key in punches:
                del punches[key]
                applied += 1
        elif action == "set":
            if key in punches:
                time_s = (rec.get("time") or "").strip()
                if time_s:
                    punches[key].epoch_us = parse_iso_us(time_s)
                    applied += 1
        elif action == "add":
            if key not in punches and key not in export_keys:
                emp = (rec.get("employee") or "").strip()
                direction = (rec.get("type") or "").strip().upper()
                time_s = (rec.get("time") or "").strip()
                if emp and direction and time_s:
                    punches[key] = Punch(site, pid, emp, direction,
                                         parse_iso_us(time_s))
                    applied += 1
    return applied


def round_punch(punch, zone):
    """Step 4: round to the nearest 6-minute mark of the site zone clock,
    keeping the UTC offset in effect at the original instant."""
    offset = dt_from_us(punch.epoch_us, zone).utcoffset()
    offset_us = int(offset.total_seconds()) * US
    wall_us = punch.epoch_us + offset_us
    rounded_wall = ((wall_us + HALF_ROUND_US) // ROUND_US) * ROUND_US
    punch.offset_us = offset_us
    punch.rounded_us = rounded_wall - offset_us


def workday_of(punch, home_zone):
    return dt_from_us(punch.rounded_us, home_zone).date()


def night_minutes(start_us, end_us, zone):
    """Elapsed minutes of [start, end) falling in 22:00-06:00 site-local."""
    total = 0
    start_s = start_us // US
    end_s = end_us // US
    for sec in range(start_s, end_s, 60):
        local = datetime.fromtimestamp(sec, tz=UTC).astimezone(zone)
        tod = local.hour * 3600 + local.minute * 60 + local.second
        if tod >= 22 * 3600 or tod < 6 * 3600:
            total += 1
    return total


def main():
    if len(sys.argv) != 3:
        print("usage: payroll.py INPUT_DIR OUTPUT_FILE", file=sys.stderr)
        return 2
    input_dir, output_file = sys.argv[1], sys.argv[2]

    with open(os.path.join(input_dir, "period.json"), encoding="utf-8") as fh:
        period = json.load(fh)
    start_day = date.fromisoformat(period["start"])
    end_day = date.fromisoformat(period["end"])
    cutoff_us = parse_iso_us(period["corrections_cutoff"])

    sites = {}
    with open(os.path.join(input_dir, "sites.csv"), encoding="utf-8",
              newline="") as fh:
        for rec in csv.DictReader(fh):
            sites[rec["site"].strip()] = {
                "zone": ZoneInfo(rec["timezone"].strip()),
                "format": rec["format"].strip(),
            }

    employees = {}
    home_zone = {}
    with open(os.path.join(input_dir, "employees.csv"), encoding="utf-8",
              newline="") as fh:
        for rec in csv.DictReader(fh):
            eid = rec["employee_id"].strip()
            employees[eid] = rec["name"]
            home_zone[eid] = sites[rec["home_site"].strip()]["zone"]

    rates = defaultdict(list)
    with open(os.path.join(input_dir, "rates.csv"), encoding="utf-8",
              newline="") as fh:
        for rec in csv.DictReader(fh):
            eid = rec["employee_id"].strip()
            rates[eid].append((date.fromisoformat(rec["effective_from"].strip()),
                              Decimal(rec["hourly_rate"].strip())))
    for lst in rates.values():
        lst.sort()

    # Steps 1-2.
    punches, export_keys = collect_punches(input_dir, sites)
    corrections_applied = apply_corrections(input_dir, punches, export_keys,
                                            cutoff_us)

    # Discard punches of unknown badges.
    punches = {k: p for k, p in punches.items() if p.employee in employees}

    # Step 3: drop duplicates per employee.
    by_employee = defaultdict(list)
    for punch in punches.values():
        by_employee[punch.employee].append(punch)
    kept = {}
    duplicates = {}
    for emp, lst in by_employee.items():
        lst.sort(key=lambda p: (p.epoch_us, 0 if p.direction == "OUT" else 1,
                                p.site, p.pid))
        mine, dups = [], []
        for punch in lst:
            if (mine and mine[-1].direction == punch.direction
                    and punch.epoch_us - mine[-1].epoch_us <= DUP_US):
                dups.append(punch)
            else:
                mine.append(punch)
        kept[emp] = mine
        duplicates[emp] = dups

    # Step 4: round everything kept (and duplicates, for their workdays).
    for emp, lst in kept.items():
        for punch in lst:
            round_punch(punch, sites[punch.site]["zone"])
    for emp, lst in duplicates.items():
        for punch in lst:
            round_punch(punch, sites[punch.site]["zone"])

    def in_period(day):
        return start_day <= day <= end_day

    # Step 5: pair into shifts.
    shifts = {}
    open_shifts = {}
    orphan_outs = {}
    for emp, lst in kept.items():
        eshifts, opens, orphans = [], [], []
        pending = None
        for punch in lst:
            if punch.direction == "IN":
                if pending is not None:
                    opens.append(pending)
                pending = punch
            else:
                if pending is not None:
                    if punch.rounded_us - pending.rounded_us <= MAX_SHIFT_US:
                        eshifts.append((pending, punch))
                        pending = None
                    else:
                        opens.append(pending)
                        orphans.append(punch)
                        pending = None
                else:
                    orphans.append(punch)
        if pending is not None:
            opens.append(pending)
        shifts[emp] = eshifts
        open_shifts[emp] = opens
        orphan_outs[emp] = orphans

    # Step 6: keep only items whose workday is in the period.
    period_shifts = {}
    for emp, lst in shifts.items():
        period_shifts[emp] = [(i, o) for i, o in lst
                              if in_period(workday_of(i, home_zone[emp]))]
    period_opens = {emp: sum(1 for p in lst
                             if in_period(workday_of(p, home_zone[emp])))
                    for emp, lst in open_shifts.items()}
    period_orphans = {emp: sum(1 for p in lst
                               if in_period(workday_of(p, home_zone[emp])))
                      for emp, lst in orphan_outs.items()}
    period_dups = {emp: sum(1 for p in lst
                            if in_period(workday_of(p, home_zone[emp])))
                   for emp, lst in duplicates.items()}

    # Step 7: minutes of each shift.
    shift_minutes = {}
    for emp, lst in period_shifts.items():
        zone_cache = {}
        rows = []
        for in_p, out_p in lst:
            site = in_p.site
            szone = sites[site]["zone"]
            worked = max(0, (out_p.rounded_us - in_p.rounded_us) // MIN_US)
            paid = worked - 30 if worked > 360 else worked
            night = min(night_minutes(in_p.rounded_us, out_p.rounded_us,
                                      szone), paid)
            day = workday_of(in_p, home_zone[emp])
            monday = day - timedelta(days=day.weekday())
            rows.append({"in_rounded": in_p.rounded_us, "day": day,
                         "week": monday, "paid": paid, "night": night})
        shift_minutes[emp] = rows

